companies = list_companies({})
first = list_contacts({ page: 1 })
remaining = for page in list.range(2, first.total_pages + 1) {
    result = list_contacts({ page })
    return result.items
}
contacts = fold acc = first.items for page in remaining {
    return acc + page
}

# Build domain -> company name map
domain_map = fold acc = {} for c in companies {
    return acc + { [c.domain]: c.name }
}

# Helper logic inline: normalize phone and fill company
results = for contact in contacts {
    # Phone fix
    phone = contact.phone if contact.phone != null else ""
    already_valid = regex.test(phone, "^\\+1\\d{10}$")
    digits = regex.replace(phone, "[^0-9]", "")
    fixed_phone = null
    needs_phone = false
    if already_valid {
        needs_phone = false
        fixed_phone = null
    } else if text.starts_with(digits, "1") and text.length(digits) == 11 {
        needs_phone = true
        fixed_phone = "+" + digits
    } else if text.length(digits) == 10 {
        needs_phone = true
        fixed_phone = "+1" + digits
    } else if phone != "" and not already_valid {
        # try best effort
        needs_phone = true
        fixed_phone = "+1" + text.slice(digits, text.length(digits) - 10) if text.length(digits) >= 10 else "+1" + digits
    } else {
        needs_phone = false
        fixed_phone = null
    }

    # Company fill
    company_empty = contact.company == null or contact.company == ""
    email = contact.email if contact.email != null else ""
    parts = text.split(email, "@")
    domain = parts[1] if list.length(parts) == 2 else ""
    matched_company = domain_map[domain] if domain in domain_map else null
    needs_company = company_empty and matched_company != null

    updated = null
    if needs_phone and needs_company {
        updated = update_contact({ id: contact.id, phone: fixed_phone, company: matched_company })
    } else if needs_phone {
        updated = update_contact({ id: contact.id, phone: fixed_phone })
    } else if needs_company {
        updated = update_contact({ id: contact.id, company: matched_company })
    } else {
        updated = null
    }

    return {
        phone_fixed: needs_phone,
        company_filled: needs_company
    }
}

phones_fixed = fold acc = 0 for r in results {
    return acc + (1 if r.phone_fixed else 0)
}
companies_filled = fold acc = 0 for r in results {
    return acc + (1 if r.company_filled else 0)
}

return {
    phones_fixed: phones_fixed,
    companies_filled: companies_filled,
    total_contacts: list.length(contacts),
    companies: companies
}

